import type { ReactNode } from "react";

export const pageHeaderSizeValues = ["default", "compact"] as const;

/** The top of a page: breadcrumbs, a title with badges, a description, actions on the right and tabs underneath. Every part is optional except the title. */
export interface PageHeaderSpecProps {
  /**
   * The page's title, shown as an h1 by default.
   */
  title: ReactNode;
  /**
   * Heading level of the title, 1 to 6. Keep 1 unless the header sits inside another page.
   * @default 1
   */
  headingLevel?: number;
  /**
   * One or two sentences under the title.
   */
  description?: ReactNode;
  /**
   * A Breadcrumbs component, shown above the title.
   */
  breadcrumbs?: ReactNode;
  /**
   * Badges or a status shown next to the title.
   */
  meta?: ReactNode;
  /**
   * Buttons for the right of the title. They wrap under the title on a narrow screen.
   */
  actions?: ReactNode;
  /**
   * A Tabs list (or any navigation) shown under the title.
   */
  tabs?: ReactNode;
  /**
   * Show the title and description as skeletons and mark the header busy.
   * @default false
   */
  isLoading?: boolean;
  /**
   * compact for pages with little room, such as a side panel or a dense admin screen.
   * @default "default"
   */
  size?: "default" | "compact";
  /**
   * Draw a line under the header.
   * @default false
   */
  border?: boolean;
  /**
   * Extra class names for single parts, so you can restyle one part without editing the file. Keys: root, breadcrumbs, title, meta, description, actions, tabs.
   */
  classNames?: Partial<Record<"root" | "breadcrumbs" | "title" | "meta" | "description" | "actions" | "tabs", string>>;
}

export const pageHeaderDefaults = {
  headingLevel: 1,
  isLoading: false,
  size: "default",
  border: false,
} as const;

export const pageHeaderMeta = {
  "name": "PageHeader",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;
